css:
/* 广播档案室 · Broadcast Archive
   整间房间的拟物：上面一面节目档案墙，中段是录音记录，底部一台广播控制台。
   材质走平面化实体——牛皮纸、金属铭牌、哑光塑料、指示灯，靠纸纹与丝印而不是照片贴图；
   所有纹理都用内联 SVG 噪声与渐变生成，不引外部位图（与液态玻璃、Riso 同一套做法）。

   两条结构性约定：
   1. 首页按「档案墙 → 录音记录 → 台面 → 读数」重排，用 flex order 搬动 base 骨架里
      现成的挂载点，不改 DOM。order 依赖 base 骨架 home 区的子节点顺序（见
      src/skeletons/base.html），那段改了要同步这里。
   2. 控制台抬高后所有 let 让路：--bottom 与首页 padding-bottom 一起改，阅读页跟着走。 */

html[data-theme] {
  color-scheme: light;
  --bg: #e8dfcc;
  --ink: #221f19; --muted: #675e50; --dim:#696155;
  --soft: #332d24; --meta: #675e50; --bright: #14120e;
  --line: #c6b79c; --line2: #d9cdb7;
  --accent: #9d3c2c; --accent2: #3d5a4b; --accentText: #fbf6e9;
  --good: #47694f; --warn: #a97a2c;
  --glow1: rgba(196, 132, 62, 0.16); --glow2: rgba(96, 122, 96, 0.14);
  --panel: #f7f0e1; --panel2: #efe4cd;
  --dock1: #34312a; --dock2: #24211c;
  --glass: #f7f0e1;
  --track: #dccdb2; --scroll: #b6a485; --coverbg: #d9cbb0;
  --menu: #faf4e7; --menu1: #f7f0e1; --menu2: #efe4cd; --chev: #8d8373;
  --edge: #b9a98c; --edge2: #9d3c2c;
  --hover: #f2e9d6; --tick: #c6b79c;
  --inset: transparent; --wordactive: #7e2f21; --swborder: #221f19;
  --shadow-dock: 0 26px 52px -30px rgba(28, 22, 14, 0.62);
  --serif: "Songti SC", "Noto Serif SC", "Source Han Serif SC", Georgia, serif;
  --bottom: 176px;
  --shell-nav: #2f2b24; --shell-nav2: #26231d;
  --shell-navin: #ece3cf; --shell-navmuted: #b9ad96; --shell-navline: #4a4438;
  --accent-ink:#9d3c2c;}

/* 纸面房间：暖灯打在墙顶，下面压一层细纹与噪点 */
html[data-theme] body {
  background:
    radial-gradient(1100px 520px at 50% -8%, rgba(255, 226, 176, 0.34), transparent 62%),
    repeating-linear-gradient(180deg, rgba(88, 72, 50, 0.034) 0 1px, transparent 1px 26px),
    linear-gradient(180deg, #efe7d6, #e3d9c3);
  color: var(--ink);
}
html[data-theme] body::before,
html[data-theme] body::after { content: none; }
html[data-theme] body::before {
  content: "";
  position: fixed; inset: 0; pointer-events: none; z-index: 0;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='150' height='150'><filter id='p'><feTurbulence type='fractalNoise' baseFrequency='0.82' numOctaves='3'/><feColorMatrix type='saturate' values='0'/></filter><rect width='150' height='150' filter='url(%23p)' opacity='0.3'/></svg>");
  opacity: 0.22; mix-blend-mode: multiply;
}

/* ---------- 1. 侧栏：档案柜的立面 ---------- */
html[data-theme] .sidebar {
  margin: 12px 0 12px 12px; padding: 22px 14px 18px;
  border: 1px solid #171410; border-radius: 3px;
  background: linear-gradient(178deg, #34302a, #221f1a 62%, #1c1916);
  box-shadow: inset 0 1px 0 rgba(255, 238, 205, 0.12), 0 14px 30px -24px rgba(20, 16, 10, 0.8);
  color: var(--shell-navin);
}
html[data-theme] .brand { padding: 0 6px 16px; border-bottom: 1px solid #4a4438; margin-bottom: 14px; }
html[data-theme] .brand strong, html[data-theme] .brand .brand-name {
  font: 600 15px/1.3 var(--serif); letter-spacing: 0.08em; color: #f2e9d6;
}
html[data-theme] .brand span, html[data-theme] .brand-sub {
  font: 500 8.5px/1.5 var(--mono); letter-spacing: 0.3em; color: #a99b80; text-transform: uppercase;
}
html[data-theme] .brand-mark {
  width: 30px; height: 30px; border-radius: 50%;
  border: 1px solid #6a6150; background: radial-gradient(circle at 50% 34%, #4d6152, #2b3a30 70%);
  color: #e9dfc8; font: 400 13px/1 var(--serif); box-shadow: none;
}
html[data-theme] .nav button {
  padding: 9px 11px; border: 1px solid transparent; border-radius: 2px;
  font: 500 11px/1 var(--mono); letter-spacing: 0.14em; text-transform: uppercase;
  color: #b9ad96;
}
html[data-theme] .nav button:hover { background: rgba(240, 228, 200, 0.07); border-color: #4a4438; color: #f2e9d6; }
html[data-theme] .nav button.active {
  background: rgba(240, 228, 200, 0.1); border-color: #6a6150; color: #fbf5e6;
  box-shadow: inset 2px 0 0 #c98f38;
}
html[data-theme] .nav button.active .nav-ico { color: #e8b465; }
html[data-theme] .sidebar-add, html[data-theme] .rail-toggle,
html[data-theme] .sidebar-bottom button { border-color: #4a4438; color: #b9ad96; }

/* ---------- 2. 顶栏：一条纸带 ---------- */
html[data-theme] .topbar {
  margin-top: 12px; padding: 0 16px; height: 60px;
  border: 1px solid var(--line); border-radius: 3px;
  background: linear-gradient(180deg, #faf4e6, #f2e9d6);
  box-shadow: 0 2px 0 rgba(96, 78, 52, 0.08);
  backdrop-filter: none; -webkit-backdrop-filter: none;
}
html[data-theme] .search-global,
html[data-theme] .icon-btn {
  border: 1px solid transparent; border-radius: 2px; background: none;
  color: var(--muted);
}
html[data-theme] .search-global { border-bottom-color: var(--line); border-radius: 0; }
html[data-theme] .icon-btn:hover { background: #ece2cd; color: var(--ink); }

/* ---------- 3. 首页：房间招牌 ---------- */
html[data-theme] .ledger-home {
  display: flex; flex-direction: column;
  max-width: 1240px; padding: 24px 26px 210px;
}
/* 搬动顺序：招牌 → 档案墙 → 录音记录 → 台面 → 读数。
   序号取自 base.html home 区的子节点位置（#customHomeMount 是第 1 个）。 */
html[data-theme] .ledger-home > .ledger-mast { order: 1; }
html[data-theme] .ledger-home > :nth-child(5) { order: 2; }        /* #homeOnboard */
html[data-theme] .ledger-home > :nth-child(11) { order: 3; }       /* 「推荐播客」小标题 */
html[data-theme] .ledger-home > #homeRecommended { order: 4; }     /* 档案墙 */
html[data-theme] .ledger-home > :nth-child(9) { order: 5; }        /* 「最近更新」小标题 */
html[data-theme] .ledger-home > #homeRecent { order: 6; }          /* 录音记录 */
html[data-theme] .ledger-home > :nth-child(6) { order: 7; }        /* 「继续收听」小标题 */
html[data-theme] .ledger-home > #homeContinue { order: 8; }        /* 台面 */
html[data-theme] .ledger-home > :nth-child(8) { order: 9; }        /* 继续收听的插件槽 */
html[data-theme] .ledger-home > #homeStats { order: 10; }          /* 读数 */
html[data-theme] .ledger-home > .ledger-rule { display: none; }

html[data-theme] .ledger-mast {
  position: relative;
  display: grid; grid-template-columns: minmax(0, 1fr) 236px; gap: 28px; align-items: end;
  margin-top: 14px; padding: 46px 24px 22px;
  border: 1px solid var(--line); border-radius: 3px;
  background:
    repeating-linear-gradient(180deg, rgba(96, 78, 52, 0.028) 0 1px, transparent 1px 24px),
    linear-gradient(180deg, #fbf6ea, #f3e9d5);
  box-shadow: inset 0 0 0 1px rgba(255, 252, 243, 0.7), 4px 5px 0 rgba(74, 60, 40, 0.09);
}
/* 招牌：左上角一块墨绿铭牌 */
html[data-theme] .ledger-mast::before {
  content: "私人广播档案室";
  position: absolute; left: -1px; top: -1px;
  padding: 6px 14px 6px 12px;
  background: linear-gradient(180deg, #48644f, #344c40);
  border-radius: 0 0 3px 0;
  color: #f2e9d6; font: 600 10px/1.4 var(--mono); letter-spacing: 0.26em;
  box-shadow: inset 0 1px 0 rgba(255, 246, 222, 0.22);
}
/* 右上角一枚不齐的档案章 */
html[data-theme] .ledger-mast::after {
  content: "BROADCAST ARCHIVE · EST. MMXXVI";
  position: absolute; right: 18px; top: 16px;
  padding: 4px 8px; border: 2px double rgba(157, 60, 44, 0.62); border-radius: 2px;
  color: rgba(157, 60, 44, 0.72); font: 600 7.5px/1.5 var(--mono); letter-spacing: 0.16em;
  transform: rotate(-2.4deg); opacity: 0.85;
}
html[data-theme] .ledger-mast h1 {
  font: 400 clamp(36px, 4.2vw, 54px)/0.94 var(--serif); letter-spacing: -0.02em; color: var(--ink);
  text-wrap: balance;
}
html[data-theme] .ledger-mast h1 em { color: var(--accent); font-style: italic; }
html[data-theme] .ledger-mast p { font: 400 13px/1.75 var(--serif); color: var(--muted); }
html[data-theme] .ledger-editor {
  padding: 12px 14px; border: 1px solid var(--line2); border-radius: 2px;
  background: rgba(255, 251, 238, 0.55);
}
html[data-theme] .ledger-editor .eyebrow { color: var(--accent2); letter-spacing: 0.24em; }
html[data-theme] .ledger-sub { border-top: 1px solid var(--line2); margin-top: 10px; padding-top: 8px; }

/* 检索：一张档案检索卡 */
html[data-theme] .ledger-search {
  border: 1px solid var(--line); border-bottom-width: 2px; border-radius: 2px;
  background: #fffdf6;
  box-shadow: inset 0 1px 2px rgba(96, 78, 52, 0.08);
}
html[data-theme] .ledger-search input { font: 400 13px/1 var(--serif); color: var(--ink); }
html[data-theme] .ledger-search button { color: var(--accent); }

/* 抽屉标签 */
html[data-theme] .ledger-section { margin: 26px 0 10px; }
html[data-theme] .ledger-section h3 {
  display: flex; align-items: center; gap: 9px;
  font: 600 11px/1 var(--mono); letter-spacing: 0.24em; text-transform: uppercase; color: var(--soft);
}
html[data-theme] .ledger-section h3::before {
  content: ""; width: 9px; height: 9px; flex: 0 0 9px;
  background: var(--accent); border-radius: 1px;
  box-shadow: 0 0 0 1px rgba(157, 60, 44, 0.24);
}
html[data-theme] .ledger-section small { font: 400 9px/1 var(--mono); letter-spacing: 0.16em; color: var(--dim); }

/* ---------- 4. 档案墙：牛皮纸板 + 一枚枚档案夹 ---------- */
html[data-theme] .ledger-home #homeRecommended {
  padding: 20px 18px 24px;
  border: 1px solid #c2b197; border-radius: 2px;
  background:
    radial-gradient(rgba(96, 78, 52, 0.14) 1px, transparent 1.2px) 0 0 / 22px 22px,
    linear-gradient(180deg, #e6dac0, #efe6d2);
  box-shadow: inset 0 0 0 6px rgba(255, 252, 243, 0.5), inset 0 0 0 7px rgba(150, 128, 96, 0.25);
}
html[data-theme] .pod-grid { counter-reset: ba-arch; gap: 16px; }
html[data-theme] .pod-card {
  position: relative; gap: 8px;
  padding: 0 12px 12px;
  border: 1px solid #bda98a; border-radius: 2px;
  background: linear-gradient(180deg, #f7eeda, #eee3c7);
  box-shadow: 3px 4px 0 rgba(74, 60, 40, 0.1);
  counter-increment: ba-arch;
  transition: translate 0.18s var(--ease), box-shadow 0.18s var(--ease);
}
html[data-theme] .pod-card:hover {
  translate: 0 -2px; border-color: #a8936f;
  box-shadow: 4px 8px 0 rgba(74, 60, 40, 0.14);
}
/* 档案夹顶部的编号带 */
html[data-theme] .pod-card::before {
  content: "ARCH " counter(ba-arch, decimal-leading-zero);
  position: absolute; inset: 0 0 auto 0; height: 21px;
  display: flex; align-items: center; padding-left: 12px;
  background: #e9dcbf; border-bottom: 1px solid #c8b696;
  font: 600 8px/1 var(--mono); letter-spacing: 0.26em; color: #7d6f57;
}
/* 别在带上的一枚回形针钉 */
html[data-theme] .pod-card::after {
  content: ""; position: absolute; left: 50%; top: 5px; width: 7px; height: 7px; margin-left: -3.5px;
  border-radius: 50%;
  background: radial-gradient(circle at 34% 28%, #f8e4b2, #b3812f 62%, #6d4a12);
  box-shadow: 0 1px 2px rgba(40, 30, 16, 0.35);
}
html[data-theme] .pod-card-main { padding-top: 26px; gap: 6px; }
/* 封面：贴在档案夹上的照片，留一圈白边 */
html[data-theme] .pod-art {
  border-radius: 1px;
  outline: 4px solid #fbf6ea; outline-offset: -4px;
  background: linear-gradient(150deg, #cfc0a4, #b7a487);
  filter: saturate(0.94) contrast(1.03);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.6) inset;
}
html[data-theme] .pod-card strong { font: 500 13px/1.45 var(--serif); color: var(--ink); }
html[data-theme] .pod-card .pod-name {
  font: 600 9px/1.4 var(--mono); letter-spacing: 0.22em; text-transform: uppercase; color: var(--accent);
}
html[data-theme] .pod-meta, html[data-theme] .pod-latest { font: 400 10px/1.55 var(--mono); color: var(--muted); }
html[data-theme] .pod-desc { font: 400 10.5px/1.6 var(--serif); color: var(--muted); }
html[data-theme] .pod-card:hover .pod-name { color: var(--accent2); }

/* ---------- 5. 录音记录：一条条记录带 ---------- */
html[data-theme] .ep-row {
  min-height: 56px; padding: 10px 12px 10px 14px;
  border: 1px solid #d3c5ab; border-bottom-width: 1px;
  border-left: 3px solid var(--accent);
  border-radius: 2px; margin-bottom: 7px;
  background: linear-gradient(180deg, #fbf6ea, #f4ebd8);
  box-shadow: 2px 2px 0 rgba(74, 60, 40, 0.06);
  transition: translate 0.16s var(--ease), box-shadow 0.16s var(--ease);
}
html[data-theme] .ep-row:last-child { margin-bottom: 0; border-bottom-width: 1px; }
html[data-theme] .ep-row:hover { translate: 0 -1px; box-shadow: 3px 4px 0 rgba(74, 60, 40, 0.1); }
html[data-theme] .ep-row.is-stale { opacity: 0.6; filter: grayscale(0.2); }
html[data-theme] .ep-row:hover .ep-title { color: var(--accent); }
html[data-theme] .ep-art { border-radius: 1px; outline: 2px solid #fbf6ea; outline-offset: -2px; }
html[data-theme] .ep-title { font: 500 12.5px/1.45 var(--serif); color: var(--ink); }
html[data-theme] .ep-sub, html[data-theme] .ep-head-meta {
  font: 400 9.5px/1.5 var(--mono); letter-spacing: 0.1em; color: var(--muted);
}
html[data-theme] .ep-dur, html[data-theme] .ep-time {
  font: 500 10px/1 var(--mono); letter-spacing: 0.06em; color: var(--accent2);
}

/* ---------- 6. 台面：正在听的那一盘 ---------- */
html[data-theme] .continue {
  position: relative;
  padding: 15px 16px 15px 20px;
  border: 1px solid #bda98a; border-radius: 2px;
  background: linear-gradient(180deg, #fcf7ec, #f3e9d4);
  box-shadow: 4px 5px 0 rgba(74, 60, 40, 0.1);
}
html[data-theme] .continue::before {
  content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 5px;
  background: repeating-linear-gradient(180deg, #9d3c2c 0 7px, #7e2f21 7px 14px);
}
html[data-theme] .continue::after {
  content: "ON DESK";
  position: absolute; right: 12px; top: -8px;
  padding: 2px 8px; border-radius: 2px;
  background: #3d5a4b; color: #f2e9d6;
  font: 600 7.5px/1.4 var(--mono); letter-spacing: 0.2em;
}
html[data-theme] .continue:hover { border-color: #a8936f; translate: 0 -1px; }
html[data-theme] .continue-main strong { font: 500 12.5px/1.4 var(--serif); color: var(--ink); }
html[data-theme] .continue-main span { font: 400 10px/1.5 var(--mono); color: var(--muted); }

/* ---------- 7. 读数：三张索引卡 ---------- */
html[data-theme] .stat {
  border: 1px solid #d0c1a6; border-radius: 2px;
  background:
    radial-gradient(rgba(96, 78, 52, 0.1) 1px, transparent 1.2px) 0 0 / 18px 18px,
    linear-gradient(180deg, #fbf6ea, #f2e8d4);
  padding: 12px 14px;
  box-shadow: 2px 3px 0 rgba(74, 60, 40, 0.07);
}
html[data-theme] .stat b, html[data-theme] .stat strong { color: var(--ink); font-variant-numeric: tabular-nums; }
html[data-theme] .stat span, html[data-theme] .stat label, html[data-theme] .stat em {
  font-family: var(--mono); letter-spacing: 0.16em; color: var(--dim);
}

/* ---------- 8. 节目页与单集页：一份档案的封面 ---------- */
html[data-theme] .page-head h1, html[data-theme] .page-title,
html[data-theme] .detail-hero h2 { font-family: var(--serif); color: var(--ink); letter-spacing: -0.015em; }
html[data-theme] .page-eyebrow, html[data-theme] .eyebrow,
html[data-theme] .crumb, html[data-theme] .crumb-link {
  font-family: var(--mono); letter-spacing: 0.2em; color: var(--accent2);
}
html[data-theme] .detail-hero, html[data-theme] .show-hero {
  padding: 20px; border: 1px solid var(--line); border-radius: 3px;
  background: linear-gradient(180deg, #fbf6ea, #f2e8d4);
  box-shadow: inset 0 0 0 1px rgba(255, 252, 243, 0.65), 4px 5px 0 rgba(74, 60, 40, 0.08);
}
html[data-theme] .detail-hero .pod-art, html[data-theme] .show-hero .pod-art {
  outline: 6px solid #fffdf6; outline-offset: -6px; border-radius: 1px;
  box-shadow: 0 3px 10px -6px rgba(40, 30, 16, 0.5);
}
html[data-theme] .detail-meta { font: 400 10px/1.6 var(--mono); letter-spacing: 0.14em; color: var(--muted); }
html[data-theme] .show-desc { font: 400 13px/1.75 var(--serif); color: var(--muted); }
html[data-theme] .show-desc-toggle { color: var(--accent); }
html[data-theme] .detail-actions .btn, html[data-theme] .ep-head .btn { border-radius: 2px; }

/* 卡片与按钮：纸片 + 机械键 */
html[data-theme] .card {
  padding: 20px 22px; border: 1px solid var(--line); border-radius: 3px;
  background: linear-gradient(180deg, #fbf6ea, #f4ecd9);
  box-shadow: 3px 4px 0 rgba(74, 60, 40, 0.07);
  backdrop-filter: none; -webkit-backdrop-filter: none;
}
html[data-theme] .btn {
  border: 1px solid #b3a184; border-radius: 2px;
  background: linear-gradient(180deg, #fdf8ee, #eee3cb);
  color: var(--ink); font: 600 10.5px/1 var(--mono); letter-spacing: 0.14em; text-transform: uppercase;
  box-shadow: 0 2px 0 #cdbb9c, inset 0 1px 0 #fffdf6;
}
html[data-theme] .btn:hover { background: linear-gradient(180deg, #fffdf6, #f4e9d2); }
html[data-theme] .btn:active { translate: 0 2px; box-shadow: inset 0 1px 2px rgba(74, 60, 40, 0.25); }
html[data-theme] .btn.primary {
  border-color: #7e2f21; color: var(--accentText);
  background: linear-gradient(180deg, #ab4735, #8a3324);
  box-shadow: 0 2px 0 #5f2318, inset 0 1px 0 rgba(255, 214, 190, 0.35);
}
html[data-theme] .btn.primary:hover { background: linear-gradient(180deg, #b44e3a, #913726); }

/* ---------- 9. 阅读页：一张摊开的节目文字稿 ---------- */
html[data-theme] .reader { background: #ddd2ba; }
html[data-theme] .transcript {
  background:
    repeating-linear-gradient(180deg, transparent 0 27px, rgba(96, 78, 52, 0.045) 27px 28px),
    linear-gradient(180deg, #fcf8ee, #f6eedb);
  box-shadow: inset 0 0 0 1px var(--line2), 0 18px 44px -34px rgba(40, 32, 22, 0.7);
}
html[data-theme] .cue { border-bottom: 1px solid rgba(150, 128, 96, 0.28); }
html[data-theme] .cue.active { box-shadow: inset 2px 0 0 var(--accent); }
html[data-theme] .cue .en, html[data-theme] .cue-en { font-family: var(--serif); color: var(--ink); }
html[data-theme] .cue .zh, html[data-theme] .cue-zh { font-family: var(--serif); color: #6a5f4d; }
/* 高亮 = 荧光笔划过一遍，不是色块 */
html[data-theme] .word.active,
html[data-theme] .cue.active .word {
  color: #3b2417;
  background-image: linear-gradient(180deg, transparent 56%, rgba(201, 143, 56, 0.45) 56%, rgba(201, 143, 56, 0.45) 94%, transparent 94%);
  box-shadow: none;
}
html[data-theme] .word.past { color: #4a4034; }
html[data-theme] .reader-top-actions { border-bottom: 1px solid var(--line2); background: rgba(250, 244, 230, 0.94); }
html[data-theme] .reader-show-pill { border: 1px solid var(--line); border-radius: 2px; background: #fdf8ee; }
html[data-theme] .reader-rail { border-left: 1px solid var(--line); background: #f3e9d4; }

/* ---------- 10. 广播控制台：底部那台机器 ---------- */
html[data-theme] body .dock {
  padding: 19px 26px 18px;
  border: 1px solid #100e0b; border-radius: 5px;
  background:
    repeating-linear-gradient(90deg, rgba(255, 236, 200, 0.03) 0 2px, transparent 2px 5px),
    linear-gradient(180deg, #3a352c, #26221c 58%, #1d1a15);
  box-shadow:
    0 26px 52px -30px rgba(20, 15, 9, 0.75),
    inset 0 1px 0 rgba(255, 240, 208, 0.16),
    inset 0 -1px 0 rgba(0, 0, 0, 0.6);
  backdrop-filter: none; -webkit-backdrop-filter: none;
  color: #ece3cf;
}
/* 顶部一条电平灯带 */
html[data-theme] body .dock::before {
  content: ""; position: absolute; left: 18px; right: 18px; top: 7px; height: 4px;
  border-radius: 1px;
  background: repeating-linear-gradient(90deg, #c98f38 0 9px, transparent 9px 14px);
  opacity: 0.5;
  box-shadow: inset 0 1px 0 rgba(0, 0, 0, 0.5);
}
html[data-theme] body .dock .ptitle,
html[data-theme] body .dock .dtitle { color: #f6eedb; font-family: var(--serif); }
html[data-theme] body .dock .pmeta,
html[data-theme] body .dock .dmeta { color: #a99b80; }
html[data-theme] body .dock .ptime,
html[data-theme] body .dock .ptime b { color: #bcae91; font-family: var(--mono); letter-spacing: 0.06em; }
html[data-theme] body .dock .jet,
html[data-theme] body .dock .chip { color: #a99b80; }
html[data-theme] body .dock .cover {
  border-radius: 1px; border: 1px solid #6a6150;
  box-shadow: 0 0 0 3px #14120e, 0 10px 22px -12px rgba(0, 0, 0, 0.75);
}
/* 进度：暗槽 + 琥珀走带 */
html[data-theme] body .dock .track::before {
  background: #14120e;
  box-shadow: inset 0 1px 0 rgba(0, 0, 0, 0.8), 0 1px 0 rgba(255, 238, 205, 0.12);
  border-radius: 1px;
}
html[data-theme] body .dock .pfill {
  border-radius: 1px;
  background: linear-gradient(90deg, #8a5c1c, #e0a94a);
  box-shadow: 0 0 10px rgba(224, 169, 74, 0.35);
}
html[data-theme] body .dock .pfill::after { background: #f0c178; box-shadow: 0 0 8px rgba(240, 193, 120, 0.55); }
/* 播放键：一枚琥珀色机械键 */
html[data-theme] body .dock .playbtn {
  border: 1px solid #7d5518; color: #241a0d;
  background: radial-gradient(circle at 50% 30%, #f2c983, #cf9539 62%, #8a5c1c);
  box-shadow:
    inset 0 2px 0 rgba(255, 246, 220, 0.6),
    inset 0 -3px 6px rgba(70, 40, 10, 0.5),
    0 10px 20px -12px rgba(160, 110, 30, 0.85);
}
html[data-theme] body .dock .skipbtn,
html[data-theme] body .dock .dockicon {
  border-color: #4a4438; color: #bcae91; background: #2a2620;
  border-radius: 2px;
}
html[data-theme] body .dock .skipbtn:hover,
html[data-theme] body .dock .dockicon:hover { color: #f6eedb; border-color: #7d7259; background: #33302a; }
html[data-theme] body .dock .dockquickbtn,
html[data-theme] body .dock .toolsbtn { color: #b7a98d; border-color: transparent; border-radius: 2px; }
html[data-theme] body .dock .dockquickbtn:hover,
html[data-theme] body .dock .toolsbtn:hover { color: #f6eedb; border-color: #4a4438; background: rgba(240, 228, 200, 0.06); }
html[data-theme] body .dock .round-play { background: #2a2620; color: #cf9539; border: 1px solid #4a4438; }
html[data-theme] body .dock .round-play:hover { background: #cf9539; color: #241a0d; }
html[data-theme] body .dock :focus-visible { outline-color: #e0a94a; }
html[data-theme] .jumppill { border-radius: 2px; border-color: #7d7259; background: #2a2620; color: #e0a94a; }

/* ---------- 11. 独立迷你窗：一只纸面遥控器 ---------- */
html[data-theme] .mini-player {
  border: 1px solid #bda98a; border-radius: 3px;
  background: var(--panel) !important;
  box-shadow: 0 18px 36px -26px rgba(30, 24, 16, 0.6);
}
html[data-theme] .mini-player::before {
  content: ""; position: absolute; left: 0; right: 0; top: 0; height: 3px;
  background: repeating-linear-gradient(90deg, #c98f38 0 8px, transparent 8px 13px);
  opacity: 0.55;
}
html[data-theme] .mini-caption { border-bottom: 1px solid var(--line2); background: #fdf8ee; }
html[data-theme] .mini-info strong { font-family: var(--serif); color: var(--ink); }
html[data-theme] .mini-info small { font-family: var(--mono); color: var(--muted); }

/* ---------- 12. 播放工具面板 ---------- */
html[data-theme] .docksheet {
  border: 1px solid #100e0b; border-radius: 4px;
  background: linear-gradient(180deg, #3a352c, #26221c);
  box-shadow: 0 30px 60px -34px rgba(20, 15, 9, 0.8);
  color: #ece3cf;
}
html[data-theme] .dshead { border-bottom: 1px solid #4a4438; }
html[data-theme] .dshead .dtitle { color: #f6eedb; font-family: var(--serif); }
html[data-theme] .dstile {
  border: 1px solid #4a4438; border-radius: 2px;
  background: #2e2a24; color: #d6c8ab;
  font: 600 10px/1.3 var(--mono); letter-spacing: 0.1em;
}
html[data-theme] .dstile:hover { background: #38342c; color: #f6eedb; border-color: #7d7259; }
html[data-theme] .dstile[aria-pressed="true"],
html[data-theme] .dstile[aria-expanded="true"] {
  background: #cf9539; color: #241a0d; border-color: #7d5518;
}
html[data-theme] .dspill {
  border: 1px solid #4a4438; border-radius: 2px; background: #2e2a24; color: #d6c8ab;
  font: 600 10px/1 var(--mono);
}
html[data-theme] .dsmute { border-radius: 2px; border: 1px solid #4a4438; background: #2e2a24; color: #d6c8ab; }
html[data-theme] .dsrange::-webkit-slider-thumb {
  -webkit-appearance: none; width: 13px; height: 19px; border-radius: 2px;
  background: #cf9539; border: 1px solid #7d5518;
}
html[data-theme] .dshint, html[data-theme] .dsnote, html[data-theme] .dsglabel { color: #a99b80; }

/* ---------- 13. 壁纸模式：熄灯后的房间 ---------- */
html[data-theme] .wallpaper { background: #17140f; color: #f2e9d6; }
html[data-theme] .wp-bg { filter: blur(40px) saturate(70%) brightness(0.9); opacity: 0.3; }
html[data-theme] .wp-shade {
  background:
    linear-gradient(90deg, rgba(20, 17, 12, 0.96) 0%, rgba(20, 17, 12, 0.9) 46%, rgba(20, 17, 12, 0.74) 76%, rgba(20, 17, 12, 0.96) 100%),
    linear-gradient(0deg, rgba(201, 143, 56, 0.14), transparent 48%);
}
html[data-theme] .wp-kicker { color: #e0a94a; font-family: var(--mono); letter-spacing: 0.24em; }
html[data-theme] .wp-title { color: #f7efdc; font-family: var(--serif); }
html[data-theme] .wp-cue.past, html[data-theme] .wp-cue.future { color: rgba(242, 233, 214, 0.58); }
html[data-theme] .wp-cue.active::before { background: #9d3c2c; width: clamp(4px, 0.32vw, 5px); border-radius: 0; }
html[data-theme] .wp-cue.active .wp-en { color: #fdf8ee; }
html[data-theme] .wp-word.active {
  color: #fdf8ee;
  background-image: linear-gradient(180deg, transparent 56%, rgba(201, 143, 56, 0.5) 56%, rgba(201, 143, 56, 0.5) 94%, transparent 94%);
  border-radius: 0;
}
html[data-theme] .wp-zh { color: rgba(242, 233, 214, 0.7); }
html[data-theme] .wp-label { color: rgba(242, 233, 214, 0.4); }
html[data-theme] .wpbtn {
  border: 1px solid #4a4438; border-radius: 2px;
  background: #2a2620; color: #d6c8ab;
  font: 600 10px/1 var(--mono); letter-spacing: 0.1em;
}
html[data-theme] .wpbtn:hover { background: #cf9539; border-color: #7d5518; color: #241a0d; }

/* ---------- 14. 设置与弹层：档案表单 ---------- */
html[data-theme] .settings-menu {
  padding: 8px; border: 1px solid var(--line); border-radius: 2px;
  background: #f5ebd7;
}
html[data-theme] .settings-menu button { border-radius: 2px; font-family: var(--mono); letter-spacing: 0.1em; }
html[data-theme] .settings-menu button.active { background: #fffdf6; color: var(--ink); box-shadow: inset 2px 0 0 var(--accent); }
html[data-theme] .setting-row { border-bottom: 1px solid var(--line2); }
html[data-theme] .ct-box {
  border: 1px solid var(--line); border-radius: 3px;
  background: linear-gradient(180deg, #fbf6ea, #f2e8d4);
  box-shadow: 3px 4px 0 rgba(74, 60, 40, 0.07);
}
html[data-theme] .ct-code, html[data-theme] #ctCss, html[data-theme] #ctHtml {
  border: 1px solid var(--line); border-radius: 2px;
  background: #fffdf6; color: var(--ink); font-family: var(--mono);
}
html[data-theme] .modal-card {
  border: 1px solid var(--line); border-radius: 3px;
  background: linear-gradient(180deg, #fbf6ea, #f2e8d4);
  box-shadow: 0 30px 60px -34px rgba(30, 24, 16, 0.7);
}
html[data-theme] .modal-head { border-bottom: 1px solid var(--line2); }
html[data-theme] .toast { border: 1px solid #7d5518; border-radius: 2px; background: #2e2a24; color: #f6eedb; }

/* 输入控件统一成纸质表单 */
html[data-theme] :where(input[type="text"], input[type="search"], input[type="number"], textarea, select) {
  border-color: var(--line); border-radius: 2px; background: #fffdf6; color: var(--ink);
}
html[data-theme] .online-row, html[data-theme] .dl-row { border-color: var(--line2); }
html[data-theme] .dl-row:hover, html[data-theme] .online-row:hover { background: #f6edda; }

html[data-theme] ::-webkit-scrollbar-thumb { background: #b6a485; border-radius: 1px; }
html[data-theme] ::selection { background: color-mix(in srgb, var(--accent) 24%, transparent); }

/* ---------- 15. 响应式：房间收成一间小屋 ---------- */
@media (max-width: 1180px) {
  html[data-theme] .ledger-mast { grid-template-columns: minmax(0, 1fr) 200px; gap: 20px; }
}
@media (max-width: 900px) {
  html[data-theme] { --bottom: 150px; }
  html[data-theme] .ledger-home { padding: 14px 14px 172px; }
  html[data-theme] .ledger-mast { grid-template-columns: minmax(0, 1fr); padding: 42px 18px 18px; }
  html[data-theme] .ledger-mast::after { display: none; }
  html[data-theme] .ledger-mast h1 { font-size: clamp(30px, 8vw, 42px); }
  html[data-theme] .ledger-editor { display: none; }
  /* 窄屏不倾斜：一行只有两张卡，透视会把字挤扁，不如老实用正面。
     真正回正的规则放在第 16 节之后，否则会被后面的 3D 规则压回去。 */
  html[data-theme] .ledger-home #homeRecommended { padding: 14px 12px 16px; }
  html[data-theme] .ledger-mast { transform: none; }
  html[data-theme] .pod-card,
  html[data-theme] .pod-card:nth-child(2n),
  html[data-theme] .pod-card:nth-child(3n) { transform: none; }
  html[data-theme] .pod-grid { gap: 12px; }
  html[data-theme] .pod-card { padding: 0 10px 10px; }
  html[data-theme] .ep-row { padding: 9px 10px; }
  html[data-theme] body .dock { padding: 15px 16px 14px; }
  html[data-theme] body .dock::before { left: 12px; right: 12px; }
  html[data-theme] .transcript { background: linear-gradient(180deg, #fcf8ee, #f6eedb); }
}
@media (max-width: 620px) {
  html[data-theme] .pod-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
  html[data-theme] .pod-card strong { font-size: 12px; }
  html[data-theme] .ledger-section h3 { font-size: 10px; letter-spacing: 0.18em; }
}

/* ---------- 16. 立体层：只用 CSS 3D，不引 WebGL ----------
   思路：房间有进深。档案墙是一块往后靠的板（rotateX），每只档案夹在板上前倾一点点，
   鼠标凑近时它朝观众抬起来（translateZ），封面再往前浮一层。全是 transform，
   没有 canvas、没有逐帧重绘，8 张卡也不掉帧。 */
html[data-theme] .ledger-home #homeRecommended {
  position: relative;
  perspective: 900px;
  perspective-origin: 50% -30%;
  transform: rotateX(calc(8deg - var(--ba-py, 0) * 2deg)) rotateY(calc(var(--ba-px, 0) * 2.4deg)) translateZ(-30px) scale(0.99);
  transform-origin: 50% -10px;
  transform-style: preserve-3d;
  transition: transform 0.3s var(--ease);
}
/* 板子内凹的暗部：墙的上沿比下沿更暗，进深才立得住 */
html[data-theme] .ledger-home #homeRecommended::before {
  content: "";
  position: absolute; inset: 0; pointer-events: none; border-radius: 2px;
  background: linear-gradient(180deg, rgba(58, 44, 26, 0.22), rgba(58, 44, 26, 0.06) 26%, transparent 56%);
  box-shadow: inset 0 2px 6px rgba(58, 44, 26, 0.25);
}
/* 墙的两侧收边：左右各一道暗，墙才不是一张贴纸 */
html[data-theme] .ledger-home #homeRecommended::after {
  content: "";
  position: absolute; inset: -4px; pointer-events: none; border-radius: 2px;
  background: linear-gradient(90deg, rgba(58, 44, 26, 0.18), transparent 9%, transparent 91%, rgba(58, 44, 26, 0.18));
  box-shadow: inset 0 0 0 1px rgba(150, 128, 96, 0.16);
}
/* 档案夹按位置转角：最左最右朝里收，中间几乎正对，像贴在一面圆柱墙上 */
html[data-theme] .pod-card {
  transform-style: preserve-3d;
  transform: rotateX(-1deg) rotateY(var(--ba-cr, 0deg)) translateZ(8px);
  box-shadow: 3px 4px 0 rgba(74, 60, 40, 0.1), 14px 18px 28px -16px rgba(48, 36, 22, 0.38);
  transition: transform 0.22s var(--ease), box-shadow 0.22s var(--ease);
}
html[data-theme] .pod-card:nth-child(4n+1) { --ba-cr: 8deg; }
html[data-theme] .pod-card:nth-child(4n+2) { --ba-cr: 2.6deg; }
html[data-theme] .pod-card:nth-child(4n+3) { --ba-cr: -2.6deg; }
html[data-theme] .pod-card:nth-child(4n) { --ba-cr: -8deg; }
html[data-theme] .pod-card:hover {
  translate: none;
  transform: rotateX(0deg) rotateY(0deg) translateY(-12px) translateZ(70px) scale(1.03);
  box-shadow: 5px 10px 0 rgba(74, 60, 40, 0.14), 40px 46px 60px -30px rgba(48, 36, 22, 0.5);
}
/* 封面比档案夹再浮一层，抬起来的时候有前后错位 */
html[data-theme] .pod-card .pod-art {
  transform: translateZ(34px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.6), 0 6px 14px -6px rgba(48, 36, 22, 0.45);
}
html[data-theme] .pod-card .pod-name,
html[data-theme] .pod-card strong { transform: translateZ(10px); }

/* 招牌是挂在墙上的一块板，稍微仰一点，影子落在墙上 */
html[data-theme] .ledger-mast {
  transform: perspective(1400px) rotateX(calc(2.8deg - var(--ba-py, 0) * 0.7deg)) rotateY(calc(var(--ba-px, 0) * 1.4deg));
  transform-origin: 50% 0;
  box-shadow:
    inset 0 0 0 1px rgba(255, 252, 243, 0.7),
    4px 6px 0 rgba(74, 60, 40, 0.09),
    0 26px 40px -34px rgba(48, 36, 22, 0.5);
}

/* 台面那张正在听的盘：悬空一厘米 */
html[data-theme] .continue {
  transform-style: preserve-3d;
  transform: rotateY(calc(var(--ba-px, 0) * 1deg)) translateZ(18px);
  box-shadow: 4px 6px 0 rgba(74, 60, 40, 0.1), 14px 18px 26px -18px rgba(48, 36, 22, 0.4);
}
html[data-theme] .continue:hover { transform: rotateY(0deg) translateY(-3px) translateZ(26px); }

/* 侧栏是立着的柜体，往右投一道影，房间才有墙 */
html[data-theme] .sidebar {
  box-shadow:
    inset 1px 0 0 rgba(255, 238, 205, 0.14),
    inset -1px 0 0 rgba(0, 0, 0, 0.5),
    22px 0 44px -34px rgba(30, 24, 16, 0.55);
}
/* 顶栏压出一条投影，像搁板 */
html[data-theme] .topbar { box-shadow: 0 3px 0 rgba(96, 78, 52, 0.14), 0 14px 24px -22px rgba(48, 36, 22, 0.6); }

/* 控制台：面板前倾一点，按键往下压时有行程 */
html[data-theme] body .dock { perspective: 1200px; }
html[data-theme] body .dock .dockrow {
  transform: rotateX(calc(-1.6deg + var(--ba-py, 0) * 0.7deg));
  transform-origin: 50% 100%;
  transform-style: preserve-3d;
  transition: transform 0.3s var(--ease);
}
html[data-theme] body .dock .pcontrols { transform-style: preserve-3d; }
html[data-theme] body .dock .playbtn { transform: translateZ(6px); transition: transform 0.16s var(--ease); }
html[data-theme] body .dock .playbtn:hover { transform: translateZ(12px) scale(1.04); }
html[data-theme] body .dock .playbtn:active {
  transform: translateZ(0) scale(0.985);
  box-shadow: inset 0 3px 8px rgba(60, 34, 8, 0.6), inset 0 -1px 0 rgba(255, 246, 220, 0.3);
}

/* 窄屏把立体层全部回正：一行两张卡时透视只会把字挤扁 */
@media (max-width: 900px) {
  html[data-theme] .ledger-home #homeRecommended,
  html[data-theme] .ledger-mast,
  html[data-theme] .continue,
  html[data-theme] body .dock { transform: none; perspective: none; }
  html[data-theme] body .dock .dockrow { transform: none; }
  html[data-theme] .pod-card,
  html[data-theme] .pod-card:nth-child(4n+1),
  html[data-theme] .pod-card:nth-child(4n+2),
  html[data-theme] .pod-card:nth-child(4n+3),
  html[data-theme] .pod-card:nth-child(4n) { transform: none; }
  html[data-theme] .pod-card .pod-art,
  html[data-theme] .pod-card .pod-name,
  html[data-theme] .pod-card strong { transform: none; }
  html[data-theme] .pod-card:hover { transform: none; }
}

/* ---------- 17. 可访问性收尾（与七套默认主题同一套标准） ---------- */
html[data-theme] :where(.ep-dur, .dur, .time, .clock, .ptime, .dst-time, .wp-time) {
  font-variant-numeric: tabular-nums;
}
html[data-theme] :where(.page-head h1, .ledger-mast h1, .year-title, .page-head .subtitle) {
  text-wrap: balance;
}
html[data-theme] :where(button, [role="button"], [role="tab"], a[href]):focus-visible { outline-offset: 1px; }
@media (prefers-reduced-motion: reduce) {
  html[data-theme] *, html[data-theme] *::before, html[data-theme] *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
  html[data-theme] :where(.nav button, .pod-card, .continue, .stat, .dstile,
    .theme-card, .custom-card, .ep-row, .swatch, .btn):hover {
    translate: none !important; transform: none !important;
  }
}
